7	/** @var \Routing\Router $router */
8	$router = app()->router();
9	$rootPath = defined('ROOT_PATH') ? ROOT_PATH : dirname(__DIR__);
10	
11	require_once $rootPath . '/config/inside_board.php';
12	
13	$loadWorksApi = static function () use ($rootPath): void {
14	    require_once $rootPath . '/api/works.php';
15	};
16	
17	$resolveWorksView = static function (Request $req): string {
18	    $viewRaw = strtolower(trim((string) $req->query('view', 'scatter')));
19	    return in_array($viewRaw, ['scatter', 'grid'], true) ? $viewRaw : 'scatter';
20	};
21	
22	$resolvePositiveInt = static function ($value, int $default, int $min = 1, ?int $max = null): int {
23	    $validated = filter_var($value, FILTER_VALIDATE_INT);
24	    if ($validated === false) {
25	        return $default;
26	    }
27	
28	    $normalized = max($min, (int) $validated);
29	    if ($max === null) {
30	        return $normalized;
31	    }
32	
33	    return min($max, $normalized);
34	};
35	
36	$renderWorksDetailPage = static function (
37	    string $viewName,
38	    string $no,
39	    string $pageType,
40	    string $pageNamespace
41	) use ($loadWorksApi) {
42	    $loadWorksApi();
43	
44	    return render($viewName, [
45	        'no' => $no,
46	        'work' => get_work_detail($no),
47	        'pageType' => $pageType,
48	        'pageNamespace' => $pageNamespace,
49	    ]);
50	};
51	
