53	 * 공용/홈/정책
54	 * ========================= */
55	$router->get('/', function () use ($loadWorksApi) {
56	    $loadWorksApi();
57	
58	    $homeWorksResponse = get_works_list(0, 10);
59	
60	    return render('pages.index', [
61	        'pageType' => 'main',
62	        'homeWorks' => $homeWorksResponse['items'],
63	    ]);
64	})->name('home');
