81	$router->group(['prefix' => '/works'], function ($r) use (
82	    $loadWorksApi,
83	    $resolveWorksView,
84	    $resolvePositiveInt,
85	    $renderWorksDetailPage
86	) {
87	    $r->get('', function (Request $req) use ($loadWorksApi, $resolveWorksView, $resolvePositiveInt) {
88	        $loadWorksApi();
89	
90	        $view = $resolveWorksView($req);
91	        $category = resolve_works_category($req->query('category'));
92	        $perPage = 12;
93	        $page = $resolvePositiveInt($req->query('page', 1), 1);
94	
95	        return render('pages.works.index', [
96	            'pageType' => 'works',
97	            'pageNamespace' => 'works-index',
98	            'worksState' => [
99	                'view' => $view,
100	                'category' => $category,
101	                'page' => $page,
102	                'limit' => $perPage,
103	            ],
104	            'worksCategories' => get_works_categories(),
105	        ]);
106	    })->name('works.index');
107	    $r->get('/list', function (Request $req) use ($loadWorksApi, $resolvePositiveInt) {
108	        $loadWorksApi();
109	
110	        $offsetRaw = $req->query('offset', 0);
111	        $limitRaw = $req->query('limit', 8);
112	        $category = resolve_works_category($req->query('category'));
113	        $offsetValidated = filter_var($offsetRaw, FILTER_VALIDATE_INT);
114	        $limitValidated = filter_var($limitRaw, FILTER_VALIDATE_INT);
115	        if ($offsetValidated === false || $limitValidated === false) {
116	            return (new Response())->json([
117	                'error' => 'Invalid pagination parameters',
118	                'code' => 'INVALID_QUERY',
119	            ], 400);
120	        }
121	
122	        $offset = max(0, (int) $offsetValidated);
123	        $limit = $resolvePositiveInt($limitValidated, 8, 1, 24);
124	        $data = get_works_list($offset, $limit, $category);
125	
126	        return (new Response())->json([
127	            'items' => $data['items'],
128	            'nextOffset' => $data['nextOffset'],
129	            'hasMore' => $data['hasMore'],
130	        ], 200);
131	    })->name('works.list');
132	    $r->get('/view/{no}', function (Request $req, Response $res, string $no) use ($renderWorksDetailPage) {
133	        return $renderWorksDetailPage('pages.works.view', $no, 'works-view', 'works-view');
134	    })->name('works.view');
135	    $r->get('/modal/{no}', function (Request $req, Response $res, string $no) use ($renderWorksDetailPage) {
136	        return $renderWorksDetailPage('pages.works.modal', $no, 'works-modal', 'works-modal');
137	    })->name('works.modal');
138	    $r->get('/modal-component/{no}', function (Request $req, Response $res, string $no) use ($loadWorksApi) {
