143	            return response(
144	                '<div class="no-work-modal__empty">Work data not found.</div>',
145	                404,
146	                ['Content-Type' => 'text/html; charset=UTF-8']
147	            );
148	        }
149	
150	        return response(
151	            include_view('components.work-modal', ['work' => $work]),
152	            200,
153	            ['Content-Type' => 'text/html; charset=UTF-8']
154	        );
155	    })->name('works.modal.component');
156	});
