660	    /**
661	     * @return array<int, string>
662	     */
663	    private function normalizeStringList($value): array
664	    {
665	        $decoded = $this->decodeJsonValue($value);
666	        if (is_string($decoded)) {
667	            $normalized = trim($decoded, " \t\n\r\0\x0B\"'");
668	            return $normalized === '' ? [] : [$normalized];
669	        }
670	
671	        if (!is_array($decoded)) {
672	            return [];
673	        }
674	
675	        $items = [];
676	        foreach ($decoded as $item) {
677	            if (!is_string($item)) {
678	                continue;
679	            }
680	
681	            $normalized = trim($item);
682	            if ($normalized === '') {
683	                continue;
684	            }
685	
686	            $items[] = $normalized;
687	        }
688	
689	        return array_values(array_unique($items));
690	    }
691	
692	    private function decodeJsonValue($value)
693	    {
694	        if (is_array($value) || is_int($value)) {
695	            return $value;
696	        }
697	
698	        if (!is_string($value)) {
699	            return null;
700	        }
701	
702	        $normalized = trim($value);
703	        if ($normalized === '') {
704	            return null;
705	        }
706	
707	        $decoded = json_decode($normalized, true);
708	        if (json_last_error() === JSON_ERROR_NONE) {
709	            return $decoded;
710	        }
711	
712	        return $normalized;
713	    }
