715	    private function buildAssetUrl($value): ?string
716	    {
717	        $filename = trim((string) $value);
718	        if ($filename === '') {
719	            return null;
720	        }
721	
722	        if ($this->isExternalUrl($filename)) {
723	            return $filename;
724	        }
725	
726	        if (strpos($filename, '/') === 0) {
727	            return base_path($filename);
728	        }
729	
730	        return base_path(self::WORKS_UPLOAD_PATH . '/' . rawurlencode($filename));
731	    }
