754	     * AWARDS 페이지용: 노출 중이고 수상 처리된 nb_works 행.
755	     *
756	     * @return list<array{
757	     *   year: string,
758	     *   title: string,
759	     *   awardLabel: string,
760	     *   awardIcon: ?string,
761	     *   prize: string,
762	     *   detailPath: string,
763	     *   previewImage: string
764	     * }>
765	     */
766	    public function getAwardPageRows(): array
767	    {
768	        $sql = <<<'SQL'
769	SELECT
770	    `id`,
771	    `title`,
772	    `is_awarded`,
773	    `award_type`,
774	    `award_detail`,
775	    `thumb_image`,
776	    `video`,
777	    `created_at`
778	FROM `nb_works`
779	WHERE `deleted_at` IS NULL
780	  AND `is_visible` = :visible
781	  AND UPPER(TRIM(`is_awarded`)) = 'Y'
782	  AND `award_type` IS NOT NULL
783	  AND `award_type` > 0
784	ORDER BY `created_at` DESC, `id` DESC
785	SQL;
786	        $statement = $this->pdo->prepare($sql);
787	        $statement->bindValue(':visible', self::VISIBLE_VALUE, \PDO::PARAM_INT);
788	        $statement->execute();
789	        $rows = $statement->fetchAll();
790	        if (!is_array($rows)) {
791	            return [];
792	        }
793	        $out = [];
794	        foreach ($rows as $row) {
795	            if (!is_array($row)) {
796	                continue;
797	            }
798	            $award = $this->resolveAward(
799	                $row['is_awarded'] ?? null,
800	                $row['award_type'] ?? null,
801	                $row['award_detail'] ?? null
802	            );
803	            if ($award === null) {
804	                continue;
805	            }
806	            $created = $row['created_at'] ?? null;
807	            $year = '';
808	            if ($created !== null && (string) $created !== '') {
809	                $ts = strtotime((string) $created);
810	                if ($ts !== false) {
811	                    $year = date('Y', $ts);
812	                }
813	            }
814	            $detail = $award['detail'] ?? '';
815	            $prize = $detail !== null && $detail !== '' ? $detail : '';
816	            $out[] = [
817	                'year' => $year,
818	                'title' => $this->normalizeText($row['title'] ?? null) ?? '',
819	                'awardLabel' => $award['label'],
820	                'awardIcon' => $award['icon'],
821	                'prize' => $prize,
822	                'detailPath' => '/works/view/' . rawurlencode((string) ($row['id'] ?? '')),
823	                'previewImage' => $this->resolveThumbnailImage($row),
824	            ];
825	        }
826	
827	        return $out;
828	    }
829	}
